using System;
using UnityEngine;

namespace WingingIt.Effects
{
    /// <summary>
    /// The VFX pack: a prefab per <see cref="VfxKind"/>, plus the meshes the shields and the afterburner use. Generated by
    /// the editor's VfxBuilder from ArtSource/VFX/build_vfx.py's meshes; lives in a Resources folder so <see cref="Vfx"/>
    /// finds it in every scene.
    /// </summary>
    public class VfxLibrary : ScriptableObject
    {
        /// <summary>Where <see cref="Vfx"/> loads it from (a Resources path).</summary>
        public const string ResourcePath = "VfxLibrary";

        [Serializable]
        public struct Entry
        {
            public VfxKind kind;
            public VfxEffect prefab;
        }

        [SerializeField] Entry[] effects = Array.Empty<Entry>();

        [Header("Mesh renderers")]
        [Tooltip("Faceted bubble, 1 m across: the Armor Shield and the repair invulnerability bubble.")]
        public Mesh shieldMesh;
        [Tooltip("Transparent palette material for the bubble, tinted per use (_BaseColor).")]
        public Material shieldMaterial;
        [Tooltip("Jagged flame 1 m long from its origin back down -Z: the afterburner.")]
        public Mesh afterburnerMesh;
        public Material afterburnerMaterial;

        public VfxEffect Get(VfxKind kind)
        {
            foreach (var e in effects)
                if (e.kind == kind)
                    return e.prefab;
            return null;
        }

        public void SetEffects(Entry[] entries) => effects = entries;
    }
}
